const $=id=>document.getElementById(id);let state={bots:[],dcaBots:[],signalBots:[],trades:[],candles:[],chartMarkers:[],chartOffset:0,chartWindow:60,chartKey:'',chartSwipeX:null,analytics:null,advisor:null,comparison:null,scanner:null,signalHistory:null,scannerFilter:'ALL',scannerPreset:'POPULAR',analyticsDays:7,portfolio:null,view:'overview',selectedBotId:null,symbolTimer:null,signalSymbolTimer:null};
const money=(n,d=2)=>Number(n||0).toLocaleString('uk-UA',{minimumFractionDigits:d,maximumFractionDigits:d})+' USDT';
const num=(n,d=2)=>Number(n||0).toLocaleString('uk-UA',{maximumFractionDigits:d});
const priceNum=n=>{const value=Math.abs(Number(n||0));if(!value)return'0';const digits=value>=10?2:value>=1?4:Math.min(10,Math.max(4,Math.ceil(-Math.log10(value))+3));return Number(n).toLocaleString('uk-UA',{minimumFractionDigits:digits,maximumFractionDigits:digits})};
const statusName=value=>({RUNNING:'ПРАЦЮЄ',PAUSED:'ПРИЗУПИНЕНО',STOPPED:'ЗУПИНЕНО',BUY_PAUSED:'КУПІВЛІ НА ПАУЗІ',BUYS_DISABLED:'ПОКУПКИ ВИМКНЕНО',OUT_OF_RANGE:'ПОЗА КОРИДОРОМ',DRAINING:'ЗАВЕРШУЄ РОБОТУ'}[value]||value);
const profileName=value=>({RANGE_GRID:'БОКОВА СІТКА',TRAILING_GRID:'РУХОМА СІТКА',UPTREND_HYBRID_10:'ГІБРИД 10%',UPTREND_HYBRID_20:'ГІБРИД 20%',UPTREND_HYBRID_30:'ГІБРИД 30%'}[value]||value);
const stageName=value=>({WAITING_BUY:'Очікує рівня купівлі',WAITING_SELL:'Очікує продажу',BUYS_DISABLED:'Покупки вимкнено, продажі активні',OUT_OF_RANGE:'Ціна поза коридором',DRAINING:'Завершує відкриті позиції'}[value]||value);
const eventInfo=value=>({BOT_STARTED:['Бот запущено','Створено початкові рівні купівлі.'],SIGNAL_BOT_STARTED:['Сигнальний бот запущено','Очікуємо одночасного підтвердження індикаторів.'],SIGNAL_BUY_FILLED:['Сигнальна купівля','Позицію відкрито; встановлено ціль і захисний стоп.'],SIGNAL_SELL_FILLED:['Сигнальний продаж','Позицію закрито за правилами стратегії.'],BUY_FILLED:['Куплено','Позицію куплено, створено ціль продажу.'],SELL_FILLED:['Продано','Позицію продано, цикл завершено.'],GRID_RECENTERED:['Сітку пересунуто','Рівні купівлі піднято за ринком.'],BUY_SIDE_PAUSED:['Купівлі призупинено','Недостатньо доступного USDT; продажі працюють.'],BUY_SIDE_RESUMED:['Купівлі відновлено','Доступного USDT знову достатньо.'],MANUAL_BUYS_DISABLED:['Покупки вимкнено','Ручне вимкнення; продажі працюють.'],MANUAL_BUYS_ENABLED:['Покупки увімкнено','Нові покупки знову дозволені.'],PRICE_RANGE_EXITED:['Вихід із коридору','Нові покупки вимкнено; продажі працюють.'],PRICE_RANGE_REENTERED:['Повернення в коридор','Ціна повернулася, покупки знову дозволені.'],DRAIN_MODE_STARTED:['М’яке завершення','Нові покупки скасовано, очікуємо продажів.'],DRAIN_MODE_COMPLETED:['Завершено','Усі відкриті Grid-позиції закрито.'],BOT_PAUSED:['Пауза','Купівлі та продажі призупинено.'],BOT_RESUMED:['Роботу відновлено','Бот продовжив роботу.'],BOT_STOPPED:['Бот зупинено','Роботу стратегії завершено.'],BUY_BLOCKED:['Купівлю заблоковано','Захисне обмеження не дозволило купівлю.'],SELL_BLOCKED:['Продаж заблоковано','Продаж не виконано; потрібна увага.'],AUTO_PAUSED:['Автопауза','Бот призупинено після повторних помилок.'],RECENTER_LIMIT_REACHED:['Ліміт зсувів','Досягнуто добовий ліміт пересувань.'],TRAILING_UP_ENABLED:['Рух сітки увімкнено','Рівні можуть рухатися вгору.'],TRAILING_UP_DISABLED:['Рух сітки вимкнено','Рівні залишаються на місці.']}[value]);
function setupStrategyLayout(){const grid=document.querySelector('.grid-layout'),control=document.querySelector('.control-panel'),signal=document.querySelector('.signal-panel');if(!grid||!control||!signal||document.querySelector('.strategy-launch-layout'))return;const layout=document.createElement('section');layout.className='strategy-launch-layout overview-only';grid.before(layout);layout.append(control,signal)}
function localizeEventFeed(){document.querySelectorAll('#event-feed .event-row').forEach(row=>{const name=row.querySelector('.event-name'),message=row.querySelector('span:last-child'),info=name&&eventInfo(name.textContent);if(info){name.textContent=info[0];if(message)message.textContent=info[1]}})}
function localizeDynamicLabels(){const map={Rank:'Місце',Return:'Дохідність',Score:'Оцінка','Risk score':'Оцінка ризику','Max drawdown':'Макс. просадка','Buy & Hold':'Купив і тримаю','Fixed return':'Дохідність фіксованої','Trailing return':'Дохідність рухомої','Fixed просадка':'Просадка фіксованої','Trailing просадка':'Просадка рухомої','Fixed цикли':'Цикли фіксованої','Trailing цикли':'Цикли рухомої','Training Return':'Дохідність навчання','Validation Return':'Дохідність перевірки','Validation drawdown':'Просадка перевірки','Validation цикли':'Цикли перевірки','Fixed vs Trailing':'Фіксована / рухома','Walk-forward 70/30':'Перевірка 70/30',PASSED:'ПРОЙДЕНО',FAILED:'НЕ ПРОЙДЕНО'};const walker=document.createTreeWalker($('app-main')||document.querySelector('main'),NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const value=node.nodeValue.trim();if(map[value])node.nodeValue=node.nodeValue.replace(value,map[value])}}
function tone(el,value){el.classList.remove('positive','negative');el.classList.add(value>=0?'positive':'negative')}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3500)}
function showLogin(){document.body.classList.remove('online');$('login-screen').classList.remove('hidden');$('logout-button').classList.add('hidden')}
async function api(url,options){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...options}),raw=await r.text();let data;try{data=raw?JSON.parse(raw):{}}catch{data={detail:r.ok?'Сервер повернув некоректну відповідь':'Внутрішня помилка сервера'}}if(r.status===401){showLogin();throw new Error(data.detail||'Потрібна авторизація')}if(!r.ok)throw new Error(data.detail||'Помилка запиту');return data}
async function loadPortfolio(){const p=await api('/api/paper/portfolio');state.portfolio=p;$('equity').textContent=money(p.total_equity);$('quote-balance').textContent=money(p.quote_balance);$('realized-pnl').textContent=money(p.realized_pnl);tone($('realized-pnl'),p.realized_pnl);$('fees').textContent=money(p.fees_paid);renderOverview()}
async function loadTrades(){const data=await api('/api/paper/trades');state.trades=data.trades;drawChart()}
async function loadMarket(){const symbol=$('symbol').value,interval=$('interval').value,key=`${symbol}:${interval}`;const [m,k]=await Promise.all([api('/api/market/'+symbol),api(`/api/market/${symbol}/klines?interval=${interval}&limit=300`)]);if(state.chartKey!==key){state.chartKey=key;state.chartOffset=0}$('chart-title').textContent=symbol;$('market-price').textContent=priceNum(m.price)+' USDT';$('change').textContent=(m.change_24h_pct>=0?'+':'')+num(m.change_24h_pct)+'% за 24г';tone($('change'),m.change_24h_pct);state.candles=k.candles;drawChart()}
async function loadBots(){const data=await api('/api/grid/bots');state.bots=data.bots;if(state.selectedBotId&&!state.bots.some(b=>b.id===state.selectedBotId)){state.view='overview';state.selectedBotId=null}renderTabs();renderOverview();renderBots();localizeBotCards();enrichBudgetCards();enhanceMobileCards();drawChart()}
async function loadComparison(){state.comparison=await api('/api/analytics/portfolio-comparison');renderComparison()}
async function loadAdvisor(notify=false){const button=$('advisor-refresh');if(button){button.disabled=true;button.textContent='Аналізуємо…'}try{state.advisor=await api('/api/analytics/advisor');renderAdvisor();if(notify)toast('Аналітику оновлено')}finally{if(button){button.disabled=false;button.textContent='Проаналізувати зараз'}}}
async function loadScanner(){const button=$('scanner-refresh');button.disabled=true;button.textContent='Аналізуємо…';try{state.scanner=await api('/api/market/scanner');state.signalHistory=await api('/api/market/scanner/history?limit=100');renderScanner();renderSignalHistory()}finally{button.disabled=false;button.textContent='Оновити'}}
async function loadDcaBots(){const data=await api('/api/dca/bots');state.dcaBots=data.bots;renderDcaBots();localizeDcaCards()}
