async function loadMonitoring(){const [m,n]=await Promise.all([api('/api/monitoring/status'),api('/api/notifications/status')]),status=value=>({ONLINE:'ПРАЦЮЄ',OFFLINE:'НЕМАЄ ЗВ’ЯЗКУ',DISABLED:'ВИМКНЕНО',ERROR:'ПОМИЛКА'}[value]||value);$('monitor-market').textContent=status(m.market_data.status);$('monitor-market').className=m.market_data.status==='ONLINE'?'positive':'negative';$('monitor-last-price').textContent=m.market_data.last_success_at?new Date(m.market_data.last_success_at).toLocaleString('uk-UA'):'—';$('monitor-grid').textContent=`${m.grid.running} / ${m.grid.paused}`;$('monitor-dca').textContent=`${m.dca.running} / ${m.dca.paused}`;$('monitor-signal').textContent=`${m.signal.running} / ${m.signal.paused}`;$('monitor-telegram').textContent=status(n.status);$('monitor-telegram').className=n.status==='ONLINE'?'positive':n.status==='DISABLED'?'':'negative';$('telegram-test').disabled=!n.enabled;renderEvents()}
async function loadAnalytics(){const a=await api(`/api/analytics/performance?symbol=${$('symbol').value}&days=${state.analyticsDays}`);state.analytics=a;const m=a.metrics,bh=a.buy_hold_return_pct,ex=a.excess_return_pct,pf=m.profit_factor,toneValue=value=>value>=0?'positive':'negative';const common=[['Купив і тримаю',bh===null?'—':num(bh,3)+'%',''],['Перевага над ринком',ex===null?'—':num(ex,3)+'%',ex===null?'':toneValue(ex)],['Зафіксована просадка',num(m.realized_max_drawdown_pct,3)+'%',''],['Коеф. прибутку',pf===null?(m.cycles?'∞':'—'):num(pf,2),''],['Цикли',m.cycles,''],['Виграшні цикли',num(m.win_rate_pct)+'%',''],['Обсяг',money(m.volume),''],['Активний час',num(a.elapsed_hours,1)+' год',''],['Зсуви сітки',m.trailing_recenters,''],['Цикли після зсуву',m.post_recenter_cycles,''],['Результат після зсуву',money(m.post_recenter_pnl),toneValue(m.post_recenter_pnl)]];const items=m.is_hybrid?[['Загальний результат',money(m.hybrid_total_pnl),toneValue(m.hybrid_total_pnl)],['Загальна дохідність',num(m.hybrid_total_return_pct,3)+'%',toneValue(m.hybrid_total_return_pct)],['Результат сітки',money(m.grid_total_pnl),toneValue(m.grid_total_pnl)],['Дохідність сітки',num(m.grid_total_return_pct,3)+'%',toneValue(m.grid_total_return_pct)],['Результат тренду',money(m.trend_pnl),toneValue(m.trend_pnl)],['Дохідність тренду',num(m.trend_return_pct,3)+'%',toneValue(m.trend_return_pct)],...common,['Комісії сітки',money(m.grid_fees),''],['Комісії тренду',money(m.trend_fees),''],['Усі комісії',money(m.fees),'']]:[['Чистий результат сітки',money(m.realized_pnl),toneValue(m.realized_pnl)],['Дохідність сітки',num(m.grid_return_pct,3)+'%',toneValue(m.grid_return_pct)],...common,['Комісії',money(m.fees),'']];$('analytics-metrics').innerHTML=items.map(([k,v,cls])=>`<div class="result-metric"><span>${k}</span><strong class="${cls}">${v}</strong></div>`).join('');$('analytics-note').textContent=a.active_since?m.is_hybrid?`Порівняння від фактичного старту: ${new Date(a.active_since).toLocaleString('uk-UA')}. Загальну дохідність розраховано на весь бюджет ${money(m.allocated_budget)}; сітку — на ${money(m.grid_budget)}, тренд — на ${money(m.trend_budget)}.`:`Порівняння від фактичного старту: ${new Date(a.active_since).toLocaleString('uk-UA')}. Дохідність сітки розраховано на бюджет ${money(m.allocated_budget)}.`:'Ще немає PAPER-подій для порівняння.';renderReadiness(a.readiness);drawAnalytics()}
function renderReadiness(r){const label=r.status==='COLLECTING_DATA'?'ЗБІР ДАНИХ':r.status==='PASSED'?'ГОТОВО':'НЕ ГОТОВО',score=r.enough_data?`Оцінка якості ${num(r.quality_score_pct)}%`:`Прогрес ${num(r.data_progress_pct)}%`,criteria=r.criteria.map(c=>`<div class="readiness-criterion ${c.passed?'pass':'fail'}"><span>${c.passed?'✓':'×'} ${c.label}</span><small>${c.target}</small></div>`).join('');$('readiness').className=`readiness ${r.status.toLowerCase()}`;$('readiness').innerHTML=`<div class="readiness-head"><div><span>Готовність стратегії</span><strong>${label}</strong></div><div><span>${score}</span><strong>${num(r.elapsed_days,1)} / ${r.minimum_days} днів · ${r.cycles} / ${r.minimum_cycles} циклів</strong></div></div><div class="progress"><i style="width:${Math.min(100,r.data_progress_pct)}%"></i></div><div class="readiness-criteria">${criteria}</div><p>${r.recommendation}</p>`}
function drawAnalytics(){const canvas=$('analytics-chart'),wrap=canvas.parentElement,ctx=canvas.getContext('2d'),dpr=devicePixelRatio||1,w=wrap.clientWidth,h=wrap.clientHeight;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const series=state.analytics?.series||[],values=series.map(x=>x.cumulative_pnl),has=values.some(x=>Math.abs(x)>1e-12);$('analytics-empty').classList.toggle('hidden',has);if(!series.length||!has)return;const left=54,right=10,top=12,bottom=27,min=Math.min(0,...values),max=Math.max(0,...values),range=max-min||1,x=i=>left+i*(w-left-right)/Math.max(1,values.length-1),y=v=>top+(max-v)*(h-top-bottom)/range;ctx.font='10px system-ui';ctx.fillStyle='#8d99aa';ctx.textAlign='right';for(let i=0;i<4;i++){const value=max-range*i/3,yy=y(value);ctx.strokeStyle='#252d3a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.fillText(`${num(value,2)} USDT`,left-5,yy+3)}ctx.textAlign='center';[0,Math.floor((series.length-1)/2),series.length-1].forEach(i=>ctx.fillText(new Date(series[i].date).toLocaleDateString('uk-UA',{day:'2-digit',month:'2-digit'}),x(i),h-7));ctx.strokeStyle=values.at(-1)>=0?'#42d39b':'#ff6b75';ctx.lineWidth=2;ctx.beginPath();values.forEach((v,i)=>i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v)));ctx.stroke();ctx.fillStyle=values.at(-1)>=0?'rgba(66,211,155,.12)':'rgba(255,107,117,.12)';ctx.lineTo(x(values.length-1),y(0));ctx.lineTo(x(0),y(0));ctx.closePath();ctx.fill()}
function botRecommendation(b){if(b.status==='PAUSED')return 'Перевірте причину паузи перед відновленням.';if(b.buy_paused)return `Покупки призупинені: доступно ${money(b.buy_available_quote)}, потрібно ${money(b.buy_required_quote)}. Продажі продовжують працювати.`;if(b.consecutive_errors)return `Зафіксовано помилок поспіль: ${b.consecutive_errors}.`;if(b.recenter_count_today>=b.max_recenters_per_day)return 'Добовий ліміт зсувів досягнуто — очікуємо автоматичного скидання.';if(b.completed_cycles<20)return `Збір PAPER-даних: ${b.completed_cycles}/20 циклів. Параметри поки не змінюйте.`;if(b.total_pnl<0)return 'Даних достатньо для аналізу, але результат від’ємний — перевірте вкладки за 7 і 30 днів.';return 'Бот працює штатно; продовжуйте PAPER-збір і контролюйте просадку.'}
function localizeBotCards(){document.querySelectorAll('#bots .bot-card').forEach(card=>{const symbol=card.querySelector('.bot-card-head strong')?.textContent,b=state.bots.find(x=>x.symbol===symbol);if(!b)return;const badge=card.querySelector('.badge');if(badge)badge.textContent=statusName(b.execution_status||b.status);card.querySelectorAll('.bot-stats>div').forEach(item=>{const label=item.querySelector('span'),value=item.querySelector('strong');if(!label||!value)return;if(label.textContent==='Профіль')value.textContent=profileName(b.strategy_profile||'RANGE_GRID');if(label.textContent==='Доступно для купівлі'){label.textContent='Залишок бюджету бота';value.textContent=money(Math.max(0,(b.grid_budget_quote||b.budget_quote)-(b.spent_quote||0)));}});const stats=card.querySelector('.bot-stats'),add=(label,value,cls='')=>{if(!stats||Array.from(stats.querySelectorAll('span')).some(x=>x.textContent===label))return;const item=document.createElement('div');item.innerHTML=`<span>${label}</span><strong class="${cls}">${value}</strong>`;stats.appendChild(item)};add('Вільно в портфелі',money(b.buy_available_quote));add('Поточний етап',stageName(b.work_stage));add('Середня ціна купівлі',b.average_open_buy_price?num(b.average_open_buy_price,6):'—');add('Вартість відкритих позицій',money(b.open_position_value_quote));add('Незакритий результат',money(b.unrealized_pnl),b.unrealized_pnl>=0?'positive':'negative');add('Найближча купівля',b.nearest_buy_price===null?'—':num(b.nearest_buy_price,6));add('Найближчий продаж',b.nearest_sell_price===null?'—':num(b.nearest_sell_price,6));const actions=card.querySelector('.bot-actions>div');if(actions&&b.status==='RUNNING'&&!b.drain_mode&&!actions.querySelector('[data-buy-control]')){const button=document.createElement('button');button.className='ghost';button.dataset.buyControl='';button.textContent=b.manual_buy_paused?'Увімкнути покупки':'Зупинити покупки';button.onclick=()=>setBuyControl(b.id,b.manual_buy_paused);actions.prepend(button);actions.insertBefore(document.createTextNode(' '),button.nextSibling);}})}
function enrichBudgetCards(){document.querySelectorAll('#bots .bot-card').forEach(card=>{const symbol=card.querySelector('.bot-card-head strong')?.textContent,b=state.bots.find(x=>x.symbol===symbol),stats=card.querySelector('.bot-stats');if(!b||!stats)return;const labels=()=>Array.from(stats.querySelectorAll('span')).map(x=>x.textContent),add=(label,value)=>{if(labels().includes(label))return;const item=document.createElement('div');item.innerHTML=`<span>${label}</span><strong>${value}</strong>`;stats.appendChild(item)},reserved=(b.open_orders||[]).filter(x=>x.side==='BUY').reduce((sum,x)=>sum+x.quote_amount*1.001,0),used=(b.grid_open_exposure_quote||0)+(b.seed_cost_quote||0);add('Використано ботом',money(used));add('Зарезервовано на купівлі',money(reserved));add('Вільний бюджет бота',money(Math.max(0,b.budget_quote-used-reserved)));})}
function enhanceMobileCards(){document.querySelectorAll('#bots .bot-card').forEach(card=>{if(card.querySelector('.mobile-details-button'))return;const button=document.createElement('button');button.type='button';button.className='mobile-details-button';button.textContent='Детальніше';button.onclick=()=>{card.classList.toggle('mobile-expanded');button.textContent=card.classList.contains('mobile-expanded')?'Згорнути':'Детальніше'};card.querySelector('.bot-stats')?.after(button)})}
function renderTabs(){const root=$('dashboard-tabs');if(!root)return;const bots=state.bots.filter(b=>b.status!=='STOPPED'),buttons=`<button type="button" class="${state.view==='overview'?'active':''}" onclick="openOverview()">Огляд</button><button type="button" class="${state.view==='advisor'?'active':''}" onclick="openAdvisor()">Аналітика</button><button type="button" class="${state.view==='scanner'?'active':''}" onclick="openScanner()">Сканер ринку</button>`+bots.map(b=>`<button type="button" class="${state.view==='bot'&&state.selectedBotId===b.id?'active':''}" onclick="openBotView('${b.id}')">${b.symbol}</button>`).join(''),options=bots.map(b=>`<option value="${b.id}" ${state.selectedBotId===b.id?'selected':''}>${b.symbol} · ${statusName(b.execution_status||b.status)}</option>`).join('');root.innerHTML=`<div class="desktop-tabs">${buttons}</div><select id="mobile-bot-select" class="mobile-bot-picker" onchange="selectMobileBot(this.value)"><option value="">Огляд і вибір бота</option>${options}</select>`}
function renderOverview(){const root=$('overview-bots'),budget=$('overview-budget');if(!root||!budget)return;const active=state.bots.filter(b=>b.status!=='STOPPED'),allocated=active.reduce((sum,b)=>sum+b.budget_quote,0),equity=state.portfolio?.total_equity||0;budget.innerHTML=`<div><span>Заявлений бюджет Grid</span><strong>${money(allocated)}</strong></div><div><span>Частка PAPER-капіталу</span><strong>${equity?num(allocated/equity*100,1):0}%</strong></div><div><span>Активні / призупинені</span><strong>${active.filter(b=>b.status==='RUNNING').length} / ${active.filter(b=>b.status==='PAUSED').length}</strong></div>`;if(!active.length){root.innerHTML='<p class="empty">Grid-ботів ще немає. Знайдіть USDT-пару нижче та створіть PAPER-бота.</p>';return}root.innerHTML=active.map(b=>`<button class="overview-bot" type="button" onclick="openBotView('${b.id}')"><span><strong>${b.symbol}</strong><small class="badge ${b.buy_paused?'buy-paused':b.status==='RUNNING'?'':'stopped'}">${statusName(b.execution_status||b.status)}</small></span><span><small>Бюджет</small><strong>${money(b.budget_quote)}</strong></span><span><small>Загальний результат</small><strong class="${b.total_pnl>=0?'positive':'negative'}">${money(b.total_pnl)}</strong></span><span><small>Цикли</small><strong>${b.completed_cycles}</strong></span><p>${botRecommendation(b)}</p></button>`).join('')}
function renderComparison(){const root=$('bot-comparison'),summary=$('comparison-summary'),data=state.comparison;if(!root||!summary||!data)return;summary.textContent=`Готові до рейтингу: ${data.eligible_bots} · Сигнали уваги: ${data.attention_count}`;if(!data.bots.length){root.innerHTML='<p class="empty">Активних Grid-ботів немає.</p>';return}const rows=data.bots.map(b=>{const healthClass=b.health.code==='ERROR'?'error':b.health.needs_attention?'attention':'',reason=b.health.needs_attention?`<small class="health-reason">${b.health.message}</small>`:'',rank=b.eligible_for_ranking?`#${b.rank}`:`Збір ${num(b.elapsed_days,1)}/7 дн · ${b.cycles}/20`;return`<tr><td><button class="ghost compact" onclick="openBotView('${b.bot_id}')">${b.symbol}</button></td><td><span class="health-pill ${healthClass}" title="${b.health.message}">${b.health.label}</span>${reason}</td><td>${money(b.budget_quote)}</td><td class="${b.total_pnl>=0?'positive':'negative'}">${money(b.total_pnl)}</td><td>${money(b.fees)}</td><td>${b.cycles}</td><td>${money(b.exposure_quote)}</td><td>${rank}</td></tr>`}).join('');root.innerHTML=`<table><thead><tr><th>Бот</th><th>Стан</th><th>Бюджет</th><th>Загальний результат</th><th>Комісії</th><th>Цикли</th><th>Залучено</th><th>Рейтинг</th></tr></thead><tbody>${rows}</tbody></table>`}
function scannerNumber(id,fallback){const value=$(id).value;return value===''?fallback:Number(value)}
function renderScanner(){const data=state.scanner,root=$('market-scanner'),summary=$('scanner-summary');if(!data)return;const labels={PAPER_CANDIDATE:'PAPER-кандидат',WATCH:'Спостерігати',OVERHEATED:'Перегріта',SKIP:'Пропустити'},active=new Set(state.bots.filter(b=>b.status!=='STOPPED').map(b=>b.symbol)),minVolume=scannerNumber('scanner-min-volume',0)*1e6,minChange=scannerNumber('scanner-min-change',-Infinity),maxChange=scannerNumber('scanner-max-change',Infinity),minRsi=scannerNumber('scanner-min-rsi',0),maxRsi=scannerNumber('scanner-max-rsi',100),minAtr=scannerNumber('scanner-min-atr',0),maxAtr=scannerNumber('scanner-max-atr',Infinity),minScore=scannerNumber('scanner-min-score',0),hideActive=$('scanner-hide-active').checked,presetMatch=x=>state.scannerPreset==='POPULAR'||state.scannerPreset==='CUSTOM'||state.scannerPreset==='GROWTH'&&x.change_24h_pct>0&&x.change_7d_pct>0&&x.price>x.ema20||state.scannerPreset==='VOLUME'&&x.volume_ratio>=1.2||state.scannerPreset==='GRID'&&x.signal==='PAPER_CANDIDATE'||state.scannerPreset==='NO_CHASE'&&x.signal==='OVERHEATED'||state.scannerPreset==='MOMENTUM'&&x.price>x.ema20&&x.ema20>x.ema50&&x.volume_ratio>=1.2&&x.rsi14>=45&&x.rsi14<=68&&x.change_24h_pct>0&&x.change_24h_pct<=8;const items=data.items.filter(x=>presetMatch(x)&&(state.scannerFilter==='ALL'||x.signal===state.scannerFilter)&&x.quote_volume_24h>=minVolume&&x.change_24h_pct>=minChange&&x.change_24h_pct<=maxChange&&x.rsi14>=minRsi&&x.rsi14<=maxRsi&&x.atr_pct>=minAtr&&x.atr_pct<=maxAtr&&x.score>=minScore&&(!hideActive||!active.has(x.symbol))).sort((a,b)=>state.scannerPreset==='POPULAR'?a.volume_rank-b.volume_rank:b.score-a.score);summary.innerHTML=`<div><span>Проаналізовано</span><strong>${data.analyzed_count} пар</strong></div><div><span>PAPER-кандидати</span><strong>${data.paper_candidates}</strong></div><div><span>Оновлено</span><strong>${new Date(data.generated_at).toLocaleString('uk-UA')}</strong></div><div><span>Після умов</span><strong>${items.length} результатів</strong></div>`;if(!items.length){root.innerHTML='<p class="empty">За вибраними умовами пар немає. Послабте фільтри або оберіть інший режим.</p>';return}root.innerHTML=`<table><thead><tr><th># / Пара</th><th>Сигнал</th><th>Пояснення</th><th>24г</th><th>7 днів</th><th>RSI</th><th>ATR</th><th>Обсяг 24г</th><th>Обсяг ×</th><th>Score</th><th>Параметри</th></tr></thead><tbody>${items.map(x=>`<tr><td><button class="ghost compact" onclick="chooseScannerPair('${x.symbol}',${x.recommended_step_pct},${x.recommended_levels_each_side})">#${state.scannerPreset==='POPULAR'?x.volume_rank:x.scanner_rank} ${x.symbol}</button></td><td><span class="signal-pill ${x.signal.toLowerCase()}">${labels[x.signal]}</span></td><td class="scanner-reason">${x.recommendation}. ${x.reasons.join(', ')}.</td><td class="${x.change_24h_pct>=0?'positive':'negative'}">${num(x.change_24h_pct)}%</td><td class="${x.change_7d_pct>=0?'positive':'negative'}">${num(x.change_7d_pct)}%</td><td>${num(x.rsi14,1)}</td><td>${num(x.atr_pct,2)}%</td><td>${money(x.quote_volume_24h)}</td><td>${num(x.volume_ratio,2)}×</td><td><strong>${x.score}/100</strong></td><td>${num(x.recommended_step_pct)}% · ${x.recommended_levels_each_side} рівнів</td></tr>`).join('')}</tbody></table>`}
function outcome(value){return value===null||value===undefined?'очікуємо':`${value>=0?'+':''}${num(value,2)}%`}
function renderSignalHistory(){const data=state.signalHistory,quality=$('signal-quality'),history=$('signal-history'),summary=$('signal-history-summary');if(!data)return;summary.textContent=`Спостережень: ${data.observations} · Перевірених типів: ${data.validated_signals}`;quality.innerHTML=data.quality.length?data.quality.map(q=>`<div class="signal-quality-card"><span>${q.signal}</span><strong class="${q.validated?'evidence-validated':'evidence-collecting'}">${q.validated?'ПЕРЕВІРЕНО':'ЗБІР ДАНИХ'}</strong><small>24г: ${q['24h'].evaluated} · точність ${q['24h'].positive_rate_pct===null?'—':num(q['24h'].positive_rate_pct)+'%'}</small><small>72г: ${q['72h'].evaluated} · середнє ${outcome(q['72h'].average_return_pct)}</small><small>7д: ${q['7d'].evaluated}/30 · середнє ${outcome(q['7d'].average_return_pct)}</small></div>`).join(''):'<p class="empty">Ще немає збережених сигналів.</p>';history.innerHTML=data.history.length?`<table><thead><tr><th>Час / Пара</th><th>Сигнал</th><th>Ціна</th><th>24г</th><th>72г</th><th>7 днів</th><th>Макс. ріст</th><th>Макс. падіння</th><th>Score</th></tr></thead><tbody>${data.history.map(x=>`<tr><td>${new Date(x.observed_at).toLocaleString('uk-UA')} · ${x.symbol}</td><td><span class="signal-pill ${x.signal.toLowerCase()}">${x.signal}</span></td><td>${num(x.entry_price,6)}</td><td>${outcome(x.return_24h_pct)}</td><td>${outcome(x.return_72h_pct)}</td><td>${outcome(x.return_7d_pct)}</td><td class="positive">${outcome(x.max_rise_pct)}</td><td class="negative">${outcome(x.max_drop_pct)}</td><td>${x.score}/100</td></tr>`).join('')}</tbody></table>`:'<p class="empty">Історія з’явиться після першого сканування.</p>'}
function renderAdvisor(){const data=state.advisor,summary=$('advisor-summary'),root=$('advisor-bots'),note=$('advisor-caveat');if(!data||!summary||!root)return;const s=data.summary,metric=(label,value,cls='')=>`<div><span>${label}</span><strong class="${cls}">${value}</strong></div>`;summary.innerHTML=metric('Загальний капітал',money(s.total_equity))+metric('Загальний результат',money(s.total_result),s.total_result>=0?'positive':'negative')+metric('Зафіксовано',money(s.realized_pnl),s.realized_pnl>=0?'positive':'negative')+metric('У відкритих позиціях',money(s.unrealized_pnl),s.unrealized_pnl>=0?'positive':'negative')+metric('Комісії',money(s.fees),'negative')+metric('Використано бюджету',`${num(s.capital_utilization_pct,1)}% · ${money(s.deployed_quote)}`);note.textContent=`Оновлено ${new Date(data.generated_at).toLocaleString('uk-UA')}. ${data.caveat}`;root.innerHTML=data.bots.length?data.bots.map(b=>{const m=b.metrics,actions=b.actions.map(a=>`<button type="button" class="${['SOFT_COMPLETE','PAUSE','LIQUIDATE'].includes(a.code)?'danger':'ghost'}" onclick="advisorAction('${b.bot_id}','${a.code}')">${a.label}</button>`).join('');return `<article class="advisor-card ${b.severity.toLowerCase()}"><div class="advisor-card-head"><div><strong>${b.symbol}</strong><span>${profileName(b.profile)} · ${statusName(b.status)}</span></div><b>${b.recommendation}</b></div><div class="advisor-metrics">${metric('Загальний результат',`${money(m.total_pnl)} · ${num(m.total_return_pct,2)}%`,m.total_pnl>=0?'positive':'negative')}${metric('Незакритий результат',money(m.unrealized_pnl),m.unrealized_pnl>=0?'positive':'negative')}${metric('Залучено',`${money(m.deployed_quote)} · ${num(m.deployed_pct,0)}%`)}${metric('Цикли / дні',`${m.cycles} / ${num(m.elapsed_days,1)}`)}${metric('Найстаріша позиція',m.oldest_open_hours?`${num(m.oldest_open_hours,0)} год`:'—')}${metric('Ринок',m.market_regime)}</div><ul>${b.reasons.map(x=>`<li>${x}</li>`).join('')}</ul><div class="advisor-actions">${actions}</div></article>`}).join(''):'<p class="empty">Активних Grid-ботів для аналізу немає.</p>'}
async function advisorAction(id,code){if(code==='OPEN'){openBotView(id);return}const row=state.advisor?.bots.find(b=>b.bot_id===id);if(code==='PREPARE_SIGNAL'){if(!confirm(`Підготувати Сигнальну стратегію для ${row.symbol}? Чинний Grid не буде змінено автоматично.`))return;chooseSignalStrategy(row.symbol,row.metrics.budget_quote);toast('Сигнальну форму підготовлено. Спочатку безпечно завершіть чинний Grid-бот.');return}if(code==='LIQUIDATE'){const warning=`Продати ВСІ відкриті позиції ${row?.symbol||''} за поточною PAPER-ціною? Поточний незакритий результат: ${money(row?.metrics.unrealized_pnl)}. Після продажу збиток буде зафіксовано, бот зупиниться, кошти вивільняться.`;if(!confirm(warning))return;if(prompt(`Для підтвердження введіть назву пари: ${row.symbol}`)?.toUpperCase()!==row.symbol)return}else{const prompts={STOP_BUYS:'Зупинити лише нові покупки? Продажі відкритих позицій продовжать працювати.',SOFT_COMPLETE:'Зупинити нові покупки та завершити бота після продажу відкритих позицій?',PAUSE:'Призупинити бота повністю, включно з продажами?'};if(!confirm(prompts[code]))return}const routes={STOP_BUYS:['buy-control',{enabled:false}],SOFT_COMPLETE:['soft-complete',null],PAUSE:['pause',null],LIQUIDATE:['liquidate',null]},[route,body]=routes[code];try{await api(`/api/grid/bots/${id}/${route}`,{method:'POST',body:body?JSON.stringify(body):undefined});toast(code==='STOP_BUYS'?'Нові покупки зупинено; продажі працюють':code==='LIQUIDATE'?'Усі позиції продано; кошти вивільнено':'Дію виконано');await Promise.all([loadBots(),loadPortfolio(),loadAdvisor()])}catch(e){toast(e.message)}}window.advisorAction=advisorAction;
function applyView(){document.body.classList.toggle('bot-detail',state.view==='bot');document.body.classList.toggle('scanner-view',state.view==='scanner');document.body.classList.toggle('analytics-view',state.view==='advisor');renderTabs();renderOverview();renderBots();localizeBotCards();enrichBudgetCards();enhanceMobileCards();renderEvents();renderScanner();renderSignalHistory();renderAdvisor()}
async function openBotView(id){const bot=state.bots.find(b=>b.id===id);if(!bot)return;state.view='bot';state.selectedBotId=id;$('symbol').value=bot.symbol;$('chart-title').textContent=bot.symbol;$('bt-budget').value=bot.budget_quote;$('bt-step').value=bot.step_pct;$('bt-levels').value=bot.levels_each_side;applyView();await Promise.all([loadMarket(),loadAnalytics()]).catch(e=>toast(e.message));scrollTo({top:0,behavior:'smooth'})}window.openBotView=openBotView;
function openOverview(){state.view='overview';state.selectedBotId=null;applyView();scrollTo({top:0,behavior:'smooth'})}window.openOverview=openOverview;
function selectMobileBot(id){if(id)openBotView(id);else openOverview()}window.selectMobileBot=selectMobileBot;
function focusBotPicker(){if(state.view!=='overview')openOverview();setTimeout(()=>{$('mobile-bot-select')?.focus();$('dashboard-tabs')?.scrollIntoView({behavior:'smooth'})},100)}window.focusBotPicker=focusBotPicker;
async function openScanner(){state.view='scanner';state.selectedBotId=null;applyView();if(!state.scanner)await loadScanner().catch(e=>toast(e.message));scrollTo({top:0,behavior:'smooth'})}window.openScanner=openScanner;
async function openAdvisor(){state.view='advisor';state.selectedBotId=null;applyView();await loadAdvisor().catch(e=>toast(e.message));scrollTo({top:0,behavior:'smooth'})}window.openAdvisor=openAdvisor;
async function chooseScannerPair(symbol,step,levels,profile='AUTO'){$('symbol').value=symbol;$('step').value=step;$('levels').value=levels;$('strategy-profile').value=profile==='WAIT'?'AUTO':profile;openOverview();await analyzeGrid().catch(e=>toast(e.message));document.querySelector('.control-panel').scrollIntoView({behavior:'smooth'})}window.chooseScannerPair=chooseScannerPair;
function renderBots(){const root=$('bots'),visible=state.view==='bot'?state.bots.filter(b=>b.id===state.selectedBotId):state.bots;if(!visible.length){root.innerHTML='<p class="empty">Активних ботів ще немає.</p>';return}root.innerHTML=visible.map(b=>`<article class="bot-card"><div class="bot-card-head"><strong>${b.symbol}</strong><span class="badge ${b.buy_paused||b.out_of_range||b.drain_mode?'buy-paused':b.status==='RUNNING'?'':'stopped'}">${b.execution_status||b.status}</span></div><div class="bot-stats"><div><span>Бюджет</span><strong>${money(b.budget_quote)}</strong></div><div><span>Профіль</span><strong>${b.strategy_profile||'RANGE_GRID'}</strong></div><div><span>Загальний результат</span><strong class="${b.total_pnl>=0?'positive':'negative'}">${money(b.total_pnl)}</strong></div><div><span>Результат сітки</span><strong class="${b.grid_pnl>=0?'positive':'negative'}">${money(b.grid_pnl)}</strong></div><div><span>Результат тренду</span><strong class="${b.trend_pnl>=0?'positive':'negative'}">${money(b.trend_pnl)}</strong></div><div><span>Бюджет сітки / тренду</span><strong>${money(b.grid_budget_quote)} / ${money(b.seed_cost_quote)}</strong></div><div><span>Доступно для купівлі</span><strong class="${b.buy_paused?'negative':''}">${money(b.buy_available_quote)}</strong></div><div><span>Потрібно для купівлі</span><strong>${money(b.buy_required_quote)}</strong></div><div><span>Ціновий коридор</span><strong>${b.price_floor?`${num(b.price_floor,4)} — ${num(b.price_ceiling,4)}`:'Без меж'}</strong></div><div><span>Макс. залучено</span><strong>${money(b.max_deployed_quote)}</strong></div><div><span>Дохідність залученого</span><strong class="${b.return_on_max_deployed_pct>=0?'positive':'negative'}">${num(b.return_on_max_deployed_pct,3)}%</strong></div><div><span>Завершено циклів</span><strong>${b.completed_cycles}</strong></div><div><span>Рівні купівлі / продажу</span><strong>${b.open_buy_orders} / ${b.open_sell_orders}</strong></div><div><span>Залучено в сітці</span><strong>${money(b.grid_open_exposure_quote)}</strong></div><div><span>Трендова позиція</span><strong>${money(b.seed_value_quote)}</strong></div><div><span>Рух сітки</span><strong class="${b.trailing_up_enabled?'positive':''}">${b.trailing_up_enabled?'УВІМКНЕНО':'ВИМКНЕНО'}</strong></div><div><span>Зсувів сьогодні</span><strong>${b.recenter_count_today} / ${b.max_recenters_per_day}</strong></div><div><span>Опорна ціна</span><strong>${num(b.reference_price,4)}</strong></div><div><span>Наступний зсув</span><strong>${b.next_recenter_price===null?'—':num(b.next_recenter_price,4)}</strong></div><div><span>Останній зсув</span><strong>${b.last_recenter_at?new Date(b.last_recenter_at).toLocaleString('uk-UA'):'—'}</strong></div></div>${b.open_positions.length?`<div class="positions-table"><h3>Відкриті позиції</h3><table><thead><tr><th>Купівля</th><th>Сума</th><th>Ціль продажу</th><th>Поточний результат</th><th>Очікуваний прибуток</th></tr></thead><tbody>${b.open_positions.map(p=>`<tr><td>${num(p.buy_price,4)}</td><td>${money(p.cost_quote)}</td><td>${num(p.target_sell_price,4)}</td><td class="${p.current_pnl>=0?'positive':'negative'}">${money(p.current_pnl)}</td><td>${money(p.expected_net_profit)}</td></tr>`).join('')}</tbody></table></div>`:''}<p class="bot-recommendation">${botRecommendation(b)}</p><div class="bot-actions"><small>${b.paused_reason||`Крок ${num(b.step_pct)}% · Усього зсувів ${b.recenter_count}`}</small><div>${b.status!=='STOPPED'&&b.seed_position_pct===0&&!b.drain_mode?`<button class="ghost" onclick="setTrailingUp('${b.id}',${!b.trailing_up_enabled})">Рух сітки: ${b.trailing_up_enabled?'вимкнути':'увімкнути'}</button> `:''}${b.status==='RUNNING'&&!b.drain_mode?`<button class="ghost" onclick="softCompleteBot('${b.id}')">М’яко завершити</button> <button class="ghost" onclick="pauseBot('${b.id}')">Пауза</button> <button class="danger" onclick="stopBot('${b.id}')">Стоп</button>`:b.status==='PAUSED'?`<button onclick="resumeBot('${b.id}')">Відновити</button>`:''}</div></div></article>`).join('');renderEvents()}
function renderDcaBots(){const root=$('dca-bots');if(!state.dcaBots.length){root.innerHTML='<p class="empty">DCA-ботів ще немає.</p>';renderEvents();return}root.innerHTML=state.dcaBots.map(b=>`<article class="bot-card"><div class="bot-card-head"><strong>${b.symbol}</strong><span class="badge ${b.status==='RUNNING'?'':'stopped'}">${b.status}</span></div><div class="bot-stats"><div><span>Покупок</span><strong>${b.buy_count}</strong></div><div><span>Використано</span><strong>${money(b.spent_quote)}</strong></div><div><span>Одна покупка</span><strong>${money(b.order_quote)}</strong></div><div><span>Залишок бюджету</span><strong>${money(b.remaining_budget)}</strong></div></div><div class="bot-actions"><small>${b.paused_reason||`Dip −${num(b.dip_trigger_pct)}%`}</small><div>${b.status==='RUNNING'?`<button class="ghost" onclick="pauseDcaBot('${b.id}')">Pause</button> <button class="danger" onclick="stopDcaBot('${b.id}')">Stop</button>`:b.status==='PAUSED'?`<button onclick="resumeDcaBot('${b.id}')">Resume</button>`:''}</div></div></article>`).join('');renderEvents()}
