function renderEvents(){const root=$('event-feed');if(!root)return;const gridBots=state.view==='bot'?state.bots.filter(b=>b.id===state.selectedBotId):state.bots,events=[...gridBots.flatMap(b=>b.events.map(e=>({...e,strategy:'GRID',symbol:b.symbol})),),...(state.view==='bot'?[]:state.dcaBots.flatMap(b=>b.events.map(e=>({...e,strategy:'DCA',symbol:b.symbol})))),...(state.view==='bot'?[]:state.signalBots.flatMap(b=>b.events.map(e=>({...e,strategy:'SIGNAL',symbol:b.symbol}))))].sort((a,b)=>b.timestamp.localeCompare(a.timestamp)).slice(0,20);if(!events.length){root.innerHTML='<p class="empty">Подій ще немає.</p>';return}root.innerHTML=events.map(e=>`<div class="event-row"><time>${new Date(e.timestamp).toLocaleString('uk-UA')}</time><small>${e.strategy} · ${e.symbol}</small><span class="event-name ${e.event.includes('FILLED')?'fill':e.event.includes('ERROR')||e.event.includes('BLOCKED')||e.event.includes('PAUSED')?'error':''}">${e.event}</span><span>${e.message||''}</span></div>`).join('')}
