function drawChart(){
  const canvas=$('market-chart'),wrap=canvas.parentElement,ctx=canvas.getContext('2d');
  const dpr=devicePixelRatio||1,w=wrap.clientWidth,h=wrap.clientHeight;
  canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);
  const source=state.candles,end=Math.max(0,source.length-state.chartOffset),start=Math.max(0,end-state.chartWindow),c=source.slice(start,end);state.chartMarkers=[];
  if(!c.length){$('chart-empty').style.display='grid';return}
  $('chart-empty').style.display='none';
  $('chart-history-label').textContent=state.chartOffset?`${start+1}–${end} із ${source.length}`:`Останні ${c.length} свічок`;
  const symbol=$('symbol').value;
  const bot=state.bots.find(b=>b.symbol===symbol&&b.status!=='STOPPED');
  const orders=bot?.open_orders||[];
  const firstTime=c[0].open_time,lastTime=c[c.length-1].close_time;
  const trades=state.trades.filter(t=>{const time=new Date(t.timestamp).getTime();return t.symbol===symbol&&time>=firstTime&&time<=lastTime});
  const left=6,right=w<600?72:155,top=12,bottom=28;
  const corridor=bot?.price_floor&&bot?.price_ceiling?[bot.price_floor,bot.price_ceiling]:[];
  const all=[...c.flatMap(v=>[v.low,v.high]),...orders.map(o=>o.trigger_price),...trades.map(t=>t.price),...corridor];
  const min=Math.min(...all),max=Math.max(...all),pad=(max-min)*.08||1,lo=min-pad,hi=max+pad;
  const x=i=>left+i*(w-left-right)/(c.length-1),y=p=>top+(hi-p)*(h-top-bottom)/(hi-lo);
  const alert=$('chart-alert');
  if(bot&&corridor.length){const distance=Math.min(Math.abs(bot.last_price-bot.price_floor),Math.abs(bot.price_ceiling-bot.last_price)),near=distance/Math.max(bot.last_price,1e-12)*100<=bot.step_pct;if(bot.out_of_range){alert.textContent='Ціна поза коридором: нові покупки вимкнено, продажі активні.';alert.classList.remove('hidden')}else if(near){alert.textContent='Ціна наблизилася до межі коридору. Контролюйте можливе вимкнення покупок.';alert.classList.remove('hidden')}else alert.classList.add('hidden')}else alert.classList.add('hidden');
  if(corridor.length){const floorY=y(bot.price_floor),ceilingY=y(bot.price_ceiling);ctx.fillStyle='rgba(255,200,87,.045)';ctx.fillRect(left,ceilingY,w-left-right,floorY-ceilingY);[[bot.price_floor,'MIN'],[bot.price_ceiling,'MAX']].forEach(([price,label])=>{const yy=y(price);ctx.strokeStyle='#ffc857';ctx.lineWidth=1;ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#ffc857';ctx.font='bold 9px system-ui';ctx.textAlign='left';ctx.fillText(`${label} ${priceNum(price)}`,left+4,yy-4)})}
  ctx.font='10px system-ui';ctx.fillStyle='#8d99aa';ctx.textAlign='left';
  for(let i=0;i<5;i++){const price=hi-(hi-lo)*i/4,yy=y(price);ctx.strokeStyle='#202936';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();if(w>=600)ctx.fillText(priceNum(price),w-right+6,yy+3)}
  ctx.textAlign='center';
  [0,Math.floor((c.length-1)/2),c.length-1].forEach(i=>{const date=new Date(c[i].open_time);ctx.fillText(date.toLocaleString('uk-UA',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}),x(i),h-7)});
  const bar=Math.max(1,(w-left-right)/c.length*.55);
  c.forEach((v,i)=>{const xx=x(i),up=v.close>=v.open;ctx.strokeStyle=up?'#42d39b':'#ff6b75';ctx.fillStyle=ctx.strokeStyle;ctx.beginPath();ctx.moveTo(xx,y(v.high));ctx.lineTo(xx,y(v.low));ctx.stroke();ctx.fillRect(xx-bar/2,Math.min(y(v.open),y(v.close)),bar,Math.max(1,Math.abs(y(v.close)-y(v.open))))});
  const labels=orders.map(order=>({order,actualY:y(order.trigger_price)})).sort((a,b)=>a.actualY-b.actualY);
  labels.forEach((item,index)=>{item.labelY=Math.max(item.actualY,index?labels[index-1].labelY+13:top+7)});
  if(labels.length){const overflow=labels[labels.length-1].labelY-(h-bottom-3);if(overflow>0)labels.forEach(item=>item.labelY-=overflow)}
  labels.forEach(({order:o,actualY,labelY})=>{const color=o.side==='BUY'?'#42d39b':'#ff6b75',shortSide=o.side==='BUY'?'B':'S',labelX=w-right+(w<600?10:42);ctx.strokeStyle=color;ctx.setLineDash([5,5]);ctx.beginPath();ctx.moveTo(left,actualY);ctx.lineTo(w-right,actualY);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=.5;ctx.beginPath();ctx.moveTo(w-right,actualY);ctx.lineTo(labelX-3,labelY);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle=color;ctx.textAlign='left';ctx.font=`${w<600?7:10}px system-ui`;ctx.fillText(`${shortSide} ${priceNum(o.trigger_price)}`,labelX,labelY+3)});
  trades.forEach(trade=>{const time=new Date(trade.timestamp).getTime(),index=c.findIndex(v=>time>=v.open_time&&time<=v.close_time);if(index<0)return;const xx=x(index),yy=y(trade.price),buy=trade.side==='BUY';ctx.fillStyle=buy?'#42d39b':'#ff6b75';ctx.beginPath();ctx.arc(xx,yy,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#07130f';ctx.font='bold 9px system-ui';ctx.textAlign='center';ctx.fillText(buy?'B':'S',xx,yy+3);state.chartMarkers.push({x:xx,y:yy,trade})});
}
async function refresh(){try{const tasks=[loadPortfolio(),loadTrades(),loadBots(),loadDcaBots(),loadSignalBots(),loadMonitoring(),loadComparison()];if(state.view==='bot')tasks.push(loadMarket(),loadAnalytics());if(state.view==='advisor')tasks.push(loadAdvisor());await Promise.all(tasks);document.body.classList.add('online');$('status-text').textContent='PAPER · Працює'}catch(e){document.body.classList.remove('online');$('status-text').textContent='Помилка API';toast(e.message)}}
function showChartTrade(event){const canvas=$('market-chart'),tip=$('chart-tooltip'),rect=canvas.getBoundingClientRect(),mx=event.clientX-rect.left,my=event.clientY-rect.top,marker=state.chartMarkers.find(item=>Math.hypot(item.x-mx,item.y-my)<=12);if(!marker){tip.classList.add('hidden');return}const t=marker.trade,pnl=t.side==='SELL'?`<span>P&amp;L: ${money(t.realized_pnl)}</span>`:'';tip.innerHTML=`<strong class="${t.side==='BUY'?'positive':'negative'}">${t.side}_FILLED · ${t.symbol}</strong><span>${new Date(t.timestamp).toLocaleString('uk-UA')}</span><span>Ціна: ${num(t.price,t.price<10?6:2)}</span><span>Кількість: ${num(t.quantity,8)}</span><span>Сума: ${money(t.quote_amount)}</span>${pnl}`;tip.style.left=`${Math.min(rect.width-250,Math.max(4,mx+12))}px`;tip.style.top=`${Math.max(4,my-95)}px`;tip.classList.remove('hidden')}
function shiftChart(direction){const step=Math.max(12,Math.floor(state.chartWindow/2)),maxOffset=Math.max(0,state.candles.length-state.chartWindow);state.chartOffset=Math.max(0,Math.min(maxOffset,state.chartOffset+direction*step));drawChart()}window.shiftChart=shiftChart;
function gridRequest(){const floor=$('price-floor').value,ceiling=$('price-ceiling').value;return{symbol:$('symbol').value,budget_quote:+$('budget').value,step_pct:+$('step').value,levels_each_side:+$('levels').value,strategy_profile:$('strategy-profile').value,price_floor:floor?+floor:null,price_ceiling:ceiling?+ceiling:null}}
function renderGridPreflight(r){const root=$('grid-preflight'),label=r.verdict==='SUITABLE'?'ПІДХОДИТЬ':r.verdict==='CAUTION'?'УВАГА':'ЗАБЛОКОВАНО',regime=r.strategy.regime,auto=r.strategy.automation,evidence=r.strategy.profile_evidence,warnings=[...r.budget.reasons,...r.warnings,...regime.reasons,auto.reason],strategyLabel={GRID:'Grid / Hybrid',SIGNAL:'Сигнальна',WAIT:'Поки чекати'}[auto.strategy]||auto.strategy;root.className=`grid-preflight ${r.verdict.toLowerCase()}`;root.innerHTML=`<div class="grid-preflight-head"><span>${r.symbol} · ${label}</span><strong>${r.recommendation}</strong></div><div class="grid-preflight-metrics"><div>Загальна рекомендація<strong>${strategyLabel}</strong></div><div>Ринковий режим<strong>${regime.name} · ${regime.confidence_pct}%</strong></div><div>Профіль Grid<strong>${r.strategy.resolved_profile}</strong></div><div>Сигнальна оцінка<strong>${auto.signal_score}/100 · ${auto.signal_ready?'ВХІД ПІДТВЕРДЖЕНО':'ОЧІКУЄМО'}</strong></div><div>Ціновий коридор<strong>${num(r.parameters.price_floor,4)} — ${num(r.parameters.price_ceiling,4)} · ${r.parameters.corridor_mode}</strong></div><div>Перевірка 30%<strong>${evidence?`${num(evidence.validation_return_pct,3)}% · ${evidence.validation_passed?'ПРОЙДЕНО':'НЕ ПРОЙДЕНО'}`:'Не потрібна'}</strong></div><div>Обсяг за 24г<strong>${money(r.market.quote_volume_24h)}</strong></div><div>Волатильність 4г<strong>${num(r.market.average_hourly_range_pct,3)}%</strong></div><div>Орієнтовний крок<strong>${num(r.parameters.recommended_step_pct)}%</strong></div><div>Після запуску доступно<strong>${money(r.budget.remaining_after_start)}</strong></div></div>${auto.strategy==='SIGNAL'?`<button class="ghost compact" type="button" onclick="chooseSignalStrategy('${r.symbol}',${r.budget.requested_budget})">Перейти до Сигнальної стратегії</button>`:r.strategy.requested_profile==='AUTO'&&r.strategy.resolved_profile!=='WAIT'?`<button class="ghost compact" type="button" onclick="applyRecommendedProfile('${r.strategy.resolved_profile}')">Застосувати ${r.strategy.resolved_profile}</button>`:''}${warnings.length?`<ul>${warnings.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}`;return r}
