$('signal-form').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{await api('/api/signal/bots/start',{method:'POST',body:JSON.stringify(signalRequest())});toast('Сигнальний PAPER-бот запущено');await Promise.all([loadSignalBots(),loadPortfolio()])}catch(err){toast(err.message)}finally{btn.disabled=false}});
$('backtest-form').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;btn.textContent='Рахуємо…';try{const r=await api('/api/backtest/grid',{method:'POST',body:JSON.stringify({symbol:$('symbol').value,interval:$('interval').value,limit:+$('bt-limit').value,budget_quote:+$('bt-budget').value,step_pct:+$('bt-step').value,levels_each_side:+$('bt-levels').value})}),p=r.performance,items=[['Результат',money(p.net_profit)],['Return',num(p.return_pct)+'%'],['Max drawdown',num(p.max_drawdown_pct)+'%'],['Комісії',money(p.fees_paid)],['Цикли',p.completed_cycles],['Buy & hold',num(p.buy_hold_return_pct)+'%']];const root=$('backtest-result');root.innerHTML=items.map(([k,v],i)=>`<div class="result-metric"><span>${k}</span><strong class="${i<2?(p.net_profit>=0?'positive':'negative'):''}">${v}</strong></div>`).join('');root.classList.remove('hidden');toast('Backtest завершено')}catch(err){toast(err.message)}finally{btn.disabled=false;btn.textContent='Запустити backtest'}});
$('compare-trailing-button').addEventListener('click',async e=>{const btn=e.currentTarget;btn.disabled=true;btn.textContent='Порівнюємо…';try{const r=await api('/api/backtest/grid/compare-trailing',{method:'POST',body:JSON.stringify({symbol:$('symbol').value,interval:$('interval').value,limit:+$('bt-limit').value,budget_quote:+$('bt-budget').value,step_pct:+$('bt-step').value,levels_each_side:+$('bt-levels').value})}),f=r.fixed,t=r.trailing,d=r.difference,items=[['Історично краще',r.historical_winner],['Fixed return',num(f.return_pct,3)+'%'],['Trailing return',num(t.return_pct,3)+'%'],['Різниця',num(d.return_pct_points,3)+' п.п.'],['Fixed просадка',num(f.max_drawdown_pct,3)+'%'],['Trailing просадка',num(t.max_drawdown_pct,3)+'%'],['Fixed цикли',f.completed_cycles],['Trailing цикли',t.completed_cycles],['Пересування',t.recenter_count]];const root=$('compare-trailing-result');root.innerHTML=items.map(([k,v],i)=>`<div class="result-metric"><span>${k}</span><strong class="${i===0?(r.historical_winner==='TRAILING_UP'?'positive':''):i===3?(d.return_pct_points>=0?'positive':'negative'):''}">${v}</strong></div>`).join('');root.classList.remove('hidden');toast('Порівняння завершено')}catch(err){toast(err.message)}finally{btn.disabled=false;btn.textContent='Fixed vs Trailing'}});
$('optimize-button').addEventListener('click',async e=>{const btn=e.currentTarget;btn.disabled=true;btn.textContent='Перевіряємо 15 варіантів…';try{const r=await api('/api/backtest/grid/optimize',{method:'POST',body:JSON.stringify({symbol:$('symbol').value,interval:$('interval').value,limit:+$('bt-limit').value,budget_quote:+$('bt-budget').value})});const root=$('optimizer-result'),rows=r.results.slice(0,10).map(x=>`<tr class="${x.rank===1?'best':''}"><td>#${x.rank}</td><td>${num(x.step_pct)}%</td><td>${x.levels_each_side}</td><td class="${x.return_pct>=0?'positive':'negative'}">${num(x.return_pct)}%</td><td>${num(x.max_drawdown_pct)}%</td><td>${x.completed_cycles}</td><td>${money(x.fees_paid)}</td><td>${num(x.score,3)}</td></tr>`).join('');root.innerHTML=`<table><thead><tr><th>Rank</th><th>Крок</th><th>Рівні</th><th>Return</th><th>Просадка</th><th>Цикли</th><th>Комісії</th><th>Score</th></tr></thead><tbody>${rows}</tbody></table>`;root.classList.remove('hidden');toast(`Optimizer завершено: найкраще ${num(r.best.step_pct)}% / ${r.best.levels_each_side} рівнів`)}catch(err){toast(err.message)}finally{btn.disabled=false;btn.textContent='Знайти найкращі параметри'}});
$('walk-forward-button').addEventListener('click',async e=>{const btn=e.currentTarget;btn.disabled=true;btn.textContent='Перевіряємо 70/30…';try{const r=await api('/api/backtest/grid/walk-forward',{method:'POST',body:JSON.stringify({symbol:$('symbol').value,interval:$('interval').value,limit:+$('bt-limit').value,budget_quote:+$('bt-budget').value,training_pct:70})}),v=r.validation_performance,items=[['Статус',r.status],['Обрано',`${num(r.selected_parameters.step_pct)}% / ${r.selected_parameters.levels_each_side}`],['Training Return',num(r.training_performance.return_pct)+'%'],['Validation Return',num(v.return_pct)+'%'],['Validation drawdown',num(v.max_drawdown_pct)+'%'],['Validation цикли',v.completed_cycles]],root=$('walk-forward-result');root.innerHTML=items.map(([k,val],i)=>`<div class="result-metric"><span>${k}</span><strong class="${i===0?(r.status==='PASSED'?'positive':'negative'):''}">${val}</strong></div>`).join('');root.className=`walk-forward-result ${r.status.toLowerCase()}`;toast(`Walk-forward: ${r.status}`)}catch(err){toast(err.message)}finally{btn.disabled=false;btn.textContent='Walk-forward 70/30'}});
$('compare-profiles-button').addEventListener('click',async e=>{const btn=e.currentTarget;btn.disabled=true;btn.textContent='Порівнюємо профілі…';try{const r=await api('/api/backtest/grid/compare-profiles',{method:'POST',body:JSON.stringify({symbol:$('symbol').value,interval:$('interval').value,limit:+$('bt-limit').value,budget_quote:+$('bt-budget').value,step_pct:+$('bt-step').value,levels_each_side:+$('bt-levels').value})});const names={RANGE_GRID:'Боковий Grid',TRAILING_GRID:'Grid з пересуванням',UPTREND_HYBRID_10:'Трендовий Hybrid 10%',UPTREND_HYBRID_20:'Трендовий Hybrid 20%',UPTREND_HYBRID_30:'Трендовий Hybrid 30%',BUY_AND_HOLD:'Buy & Hold'},rows=r.ranking.map((name,index)=>{const p=r.profiles[name];return `<tr class="${index===0?'best':''}"><td>#${index+1}</td><td>${names[name]||name}</td><td class="${p.return_pct>=0?'positive':'negative'}">${num(p.return_pct,3)}%</td><td>${num(p.max_drawdown_pct,3)}%</td><td>${p.completed_cycles}</td><td>${money(p.fees_paid)}</td><td>${num(p.risk_adjusted_score,3)}</td></tr>`}).join(''),wf=r.walk_forward,v=wf.validation_performance,status=wf.validation_passed?'PASSED':'FAILED',rec=r.recommendation,rv=rec.validation_performance,recStatus=rec.validation_passed?'ПІДТВЕРДЖЕНО':'НЕ ПІДТВЕРДЖЕНО',regimes={UPTREND:'Висхідний ринок',RANGE:'Боковий ринок',TRENDING:'Ринок у русі'},benchmark=r.historical_winner==='BUY_AND_HOLD'?`Buy & Hold мав найкращий загальний результат, але це еталон постійного утримання активу, а не Grid-бот.`:'Grid-профіль випередив еталон Buy & Hold на цьому періоді.',root=$('compare-profiles-result');root.innerHTML=`<div class="profile-recommendation ${rec.validation_passed?'passed':'failed'}"><span>AUTO-РЕКОМЕНДАЦІЯ · ${regimes[rec.market_regime]||rec.market_regime}</span><strong>${names[rec.recommended_bot_profile]||rec.recommended_bot_profile}</strong><p>${benchmark} Рекомендацію перевірено на останніх 30% свічок: <b class="${rv.return_pct>=0?'positive':'negative'}">${num(rv.return_pct,3)}%</b> · ${recStatus}.</p></div><table><thead><tr><th>Rank</th><th>Профіль</th><th>Return</th><th>Просадка</th><th>Цикли</th><th>Комісії</th><th>Risk score</th></tr></thead><tbody>${rows}</tbody></table><div class="walk-forward-result ${status.toLowerCase()}"><div class="result-metric"><span>Загальний переможець на перших 70%</span><strong>${names[wf.selected_on_training]||wf.selected_on_training}</strong></div><div class="result-metric"><span>Результат на наступних 30%</span><strong class="${v.return_pct>=0?'positive':'negative'}">${num(v.return_pct,3)}%</strong></div><div class="result-metric"><span>Перевірка</span><strong class="${wf.validation_passed?'positive':'negative'}">${status}</strong></div></div>`;root.classList.remove('hidden');toast(`Рекомендація: ${names[rec.recommended_bot_profile]||rec.recommended_bot_profile}`)}catch(err){toast(err.message)}finally{btn.disabled=false;btn.textContent='Порівняти профілі'}});
$('login-form').addEventListener('submit',async e=>{e.preventDefault();$('login-error').textContent='';try{await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:$('login-username').value,password:$('login-password').value})});$('login-password').value='';$('login-screen').classList.add('hidden');$('logout-button').classList.remove('hidden');await refresh()}catch(err){$('login-error').textContent=err.message}});
$('logout-button').addEventListener('click',async()=>{await api('/api/auth/logout',{method:'POST'});showLogin()});
$('telegram-test').addEventListener('click',async e=>{const btn=e.currentTarget;btn.disabled=true;try{await api('/api/notifications/test',{method:'POST'});toast('Тестове повідомлення Telegram надіслано');await loadMonitoring()}catch(err){toast(err.message)}finally{btn.disabled=false}});
$('scanner-refresh').addEventListener('click',()=>loadScanner().catch(e=>toast(e.message)));
$('advisor-refresh').addEventListener('click',()=>loadAdvisor(true).catch(e=>toast(e.message)));
setInterval(()=>{if(state.view==='advisor')loadAdvisor().catch(()=>{})},300000);
$('scanner-filter').addEventListener('change',e=>{state.scannerFilter=e.target.value;renderScanner()});
$('scanner-preset').addEventListener('change',e=>{state.scannerPreset=e.target.value;renderScanner()});
['scanner-min-volume','scanner-min-change','scanner-max-change','scanner-min-rsi','scanner-max-rsi','scanner-min-atr','scanner-max-atr','scanner-min-score','scanner-hide-active'].forEach(id=>$(id).addEventListener('input',renderScanner));
$('market-chart').addEventListener('mousemove',showChartTrade);
$('market-chart').addEventListener('mouseleave',()=>$('chart-tooltip').classList.add('hidden'));
$('market-chart').addEventListener('pointerdown',e=>{state.chartSwipeX=e.clientX});
$('market-chart').addEventListener('pointerup',e=>{if(state.chartSwipeX===null)return;const distance=e.clientX-state.chartSwipeX;state.chartSwipeX=null;if(Math.abs(distance)>35)shiftChart(distance>0?1:-1)});
document.querySelectorAll('[data-days]').forEach(btn=>btn.addEventListener('click',async()=>{state.analyticsDays=+btn.dataset.days;document.querySelectorAll('[data-days]').forEach(x=>x.classList.toggle('active',x===btn));await loadAnalytics().catch(e=>toast(e.message))}));
async function loadSymbolOptions(query='',statusId='symbol-search-status'){try{const data=await api(`/api/market/symbols/search?query=${encodeURIComponent(query)}&limit=30`);$('symbol-options').innerHTML=data.symbols.map(x=>`<option value="${x.symbol}">${x.base_asset} / ${x.quote_asset}</option>`).join('');$(statusId).textContent=data.symbols.length?`Знайдено: ${data.symbols.length} · лише Spot ${data.quote_asset}`:'Активної Spot USDT-пари не знайдено'}catch(e){$(statusId).textContent='Каталог тимчасово недоступний'}}
async function selectSymbol(){const input=$('symbol');input.value=input.value.toUpperCase().replace(/[^A-Z0-9]/g,'');if(!input.value.endsWith('USDT')){toast('Оберіть активну USDT-пару зі списку');return}await Promise.all([loadMarket(),loadAnalytics()]).catch(e=>toast(e.message))}
async function init(){try{setupStrategyLayout();new MutationObserver(localizeEventFeed).observe($('event-feed'),{childList:true,subtree:true});new MutationObserver(localizeDynamicLabels).observe(document.querySelector('main'),{childList:true,subtree:true});const r=await fetch('/api/auth/status'),s=await r.json();if(s.auth_enabled&&!s.authenticated){showLogin();return}$('login-screen').classList.add('hidden');if(s.auth_enabled)$('logout-button').classList.remove('hidden');await Promise.all([refresh(),loadSymbolOptions('')]);applyView();localizeEventFeed();localizeDynamicLabels()}catch(e){toast(e.message)}}
$('refresh').onclick=refresh;$('symbol').addEventListener('input',e=>{e.target.value=e.target.value.toUpperCase().replace(/[^A-Z0-9]/g,'');clearTimeout(state.symbolTimer);state.symbolTimer=setTimeout(()=>loadSymbolOptions(e.target.value),250)});$('signal-symbol').addEventListener('input',e=>{e.target.value=e.target.value.toUpperCase().replace(/[^A-Z0-9]/g,'');clearTimeout(state.signalSymbolTimer);state.signalSymbolTimer=setTimeout(()=>loadSymbolOptions(e.target.value,'signal-symbol-status'),250)});$('signal-symbol').addEventListener('change',()=>loadSymbolOptions($('signal-symbol').value,'signal-symbol-status'));$('symbol').onchange=selectSymbol;$('interval').onchange=loadMarket;addEventListener('resize',()=>{drawChart();drawAnalytics()});init();setInterval(()=>Promise.all([loadPortfolio(),loadTrades(),loadBots(),loadDcaBots(),loadSignalBots(),loadMonitoring(),loadComparison()]).catch(()=>{}),10000);setInterval(()=>{if(state.view==='bot')loadMarket().catch(()=>{})},30000);setInterval(()=>{if(state.view==='bot')loadAnalytics().catch(()=>{})},60000);
